private void adaptQueryMethods(StringBuilder out, String request, String source) {
  java.util.regex.Pattern pattern =
      java.util.regex.Pattern.compile(
          "(template <bool P(?:, class ChildResult)?> (?:requires \\(!P\\) )?)?"
              + request
              + "& ([A-Za-z_][A-Za-z_0-9]*)\\(([^)]*)\\) \\{ (.*?)return \\*this; \\}",
          java.util.regex.Pattern.DOTALL);
  java.util.regex.Matcher matcher = pattern.matcher(source);
  int consumed = 0;
  while (matcher.find()) {
    if (!source.substring(consumed, matcher.start()).isBlank()) {
      throw new IllegalStateException("Unadapted C++ query method");
    }
    String parameters = matcher.group(3);
    String arguments = cppArguments(parameters);
    if (matcher.group(4).startsWith("selection.relation_query(")) {
      fluent(out, request, matcher.group(1), camel(matcher.group(2)), parameters, arguments,
          matcher.group(4).replace("selection.relation_query(", "query_.selectRelation(")
              .replace("child.query()", "child.runtimeQuery()"));
      consumed = matcher.end();
      continue;
    }
    String guard =
        parameters.contains("& child") ? "query_.requireCompatible(child.query_); " : "";
    fluent(
        out,
        request,
        matcher.group(1) == null ? "" : matcher.group(1),
        camel(matcher.group(2)),
        parameters,
        arguments,
        guard
            + "query_.mutate_selection([&](SelectQuery& selection) { "
            + matcher.group(4)
            + " });");
    consumed = matcher.end();
  }
  if (!source.substring(consumed).isBlank()) {
    throw new IllegalStateException("Unadapted C++ query method tail");
  }
}

private static List<FieldDescriptor> descriptorFields(ObjectDescriptor od) {
  return java.util.stream.Stream.concat(
      fields(od).stream().filter(field -> !field.isObjectProperty()),
      fields(od).stream().filter(FieldDescriptor::isObjectProperty)).toList();
}

private static List<FieldDescriptor> fields(ObjectDescriptor od) {
  return CppFieldLayoutMetadata.fields(od);
}

// Rust's derive describes scalar storage first, then generated foreign keys.
// Indexed field-layout ordering remains the separate canonical model order.

  private String assist(String ns, List<ObjectDescriptor> entities) {
    StringBuilder out =
        new StringBuilder(
            "# Generated C++ model-aware API\n\nNamespace: `"
                + ns
                + "`. Create `auto Q = user_context.queries<query_factory>();`. Allocate with"
